from collections import deque
def comp(grid,seed):
    c=grid[seed[0]][seed[1]]; H,W=len(grid),len(grid[0])
    seen={seed}; dq=deque([seed]); out=[row[:] for row in grid]
    out[seed[0]][seed[1]]=c
    while dq:
        i,j=dq.popleft()
        for di in(-1,0,1):
            for dj in(-1,0,1):
                a,b=i+di,j+dj
                if 0<=a<H and 0<=b<W and (a,b) not in seen and grid[a][b]==1:
                    seen.add((a,b)); out[a][b]=c; dq.append((a,b))
    return out
